// â”€â”€ BD settings sync â”€â”€
function bdSettingsLoad(): Record<string, any> {
    try {
        const raw = localStorage.getItem("bd_YABDP4Nitro_settings");
        return raw ? JSON.parse(raw) : {};
    } catch { return {}; }
}
function bdSettingsSave(settings: Record<string, any>) {
    try { localStorage.setItem("bd_YABDP4Nitro_settings", JSON.stringify(settings)); } catch {}
}
// Read BD defaults from the instance if available, else from localStorage
function getBdDefault(key: string, fallback: any): any {
    const s = bdSettingsLoad();
    return s[key] !== undefined ? s[key] : fallback;
}
function bdSet(key: string, value: any) {
    const s = bdSettingsLoad();
    s[key] = value;
    bdSettingsSave(s);
    // Update the running instance if it exists
    if (instance && instance.settings) {
        instance.settings[key] = value;
        if (typeof instance.saveSettings === 'function')
            instance.saveSettings();
    }
}

