const BD_SOURCE = atob("");

let instance: any = null;

function startBdPlugin() {
    if (instance) return;
    try {
        const mod = { exports: {} };
        const BdApi = createBdApi();
        try { (window as any).BdApi = BdApi; } catch {}
        const fn = new Function("module", "exports", "BdApi", "window", BD_SOURCE);
        fn(mod, mod.exports, BdApi, window);
        const cls = mod.exports;
        if (typeof cls !== "function") {
            console.warn("[bd_yabdp4nitro] No class exported");
            return;
        }
        instance = new cls({ name: "YABDP4Nitro", version: "1.0.0" });
        if (typeof instance.start === "function")
            instance.start();
        console.log("[bd_yabdp4nitro] Loaded");
    } catch (e) {
        console.error("[bd_yabdp4nitro] Error:", e);
    }
}

function stopBdPlugin() {
    if (instance && typeof instance.stop === "function") {
        try { instance.stop(); } catch {}
    }
    instance = null;
    try { (window as any).BdApi?.Patcher?.unpatchAll("bd_yabdp4nitro"); } catch {}
    const styles = document.querySelectorAll("style[id^='bd_yabdp4nitro']");
    styles.forEach(s => s.remove());
}

export default definePlugin({
    name: "YABDP4Nitro",
    description: "Unlock all screensharing modes, use cross-server & GIF emotes, and more! (BD plugin)",
    authors: [{ name: "Riolubruh" }],
    settings,
    start() { startBdPlugin(); },
    stop() { stopBdPlugin(); }
});